uv.lock
{
  "name": "slide-deck",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "test": "tsc --noEmit && eslint . && node --test --test-reporter=spec \"tests/**/*.test.ts\""
  },
  "dependencies": {
    "@eslint/js": "^10.0.1",
    "eslint": "^10.14.0",
    "pptxgenjs": "^4.0.1",
    "typescript": "~6.0.3",
    "typescript-eslint": "^8.72.2"
  },
  "devDependencies": {
    "@types/node": "^24.19.2"
  }
}
{
  "compilerOptions": {
    "target": "es2024",
    "lib": ["es2024"],
    "module": "preserve",
    "moduleResolution": "bundler",
    "types": ["node"],
    "strict": true,
    "noEmit": true,
    "allowImportingTsExtensions": true,
    "erasableSyntaxOnly": true,
    "verbatimModuleSyntax": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitOverride": true,
    "noPropertyAccessFromIndexSignature": true,
    "skipLibCheck": true
  },
  "include": ["src", "tests"]
}
import js from "@eslint/js";
import { defineConfig } from "eslint/config";
import tseslint from "typescript-eslint";

export default defineConfig(
  { ignores: ["node_modules/"] },
  {
    files: ["src/**/*.ts", "tests/**/*.ts"],
    extends: [js.configs.recommended, tseslint.configs.strictTypeChecked],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // node:test の test・describe などは Promise を返す。テストランナーがその完了まで待機するので、
      // これらを await しない呼び出しを、規則 no-floating-promises の指摘の対象から除く
      "@typescript-eslint/no-floating-promises": [
        "error",
        {
          allowForKnownSafeCalls: [
            { from: "package", package: "node:test", name: ["test", "it", "describe", "suite"] },
          ],
        },
      ],
    },
  },
);
import assert from "node:assert/strict";
import { test } from "node:test";
import pptxgen from "pptxgenjs";

test("pptxgenjs で 1 枚のスライドの PowerPoint のファイルを、ZIP の形式で書き出せる", async () => {
  const pres = new pptxgen();
  pres.addSlide().addText("smoke", { x: 1, y: 1, w: 3, h: 1 });
  const out = await pres.write({ outputType: "nodebuffer" });
  assert.ok(Buffer.isBuffer(out));
  // PowerPoint のファイルは ZIP なので、先頭の 2 バイトは ZIP のシグネチャ "PK"
  assert.equal(out.subarray(0, 2).toString("latin1"), "PK");
});
{
  "name": "slide-deck",
  "description": "図を中心にした説明資料を、構成案から PowerPoint のファイルと Google スライドの両方に作り、一部のスライドだけを直せるようにするスキルとツール",
  "version": "0.0.1",
  "author": {
    "name": "akm"
  },
  "license": "MIT"
}
eslint.config.mjs
package-lock.json
package.json
pyproject.toml
python
tests
tsconfig.json
