  text: string;
  fontSize: number;
  bold: boolean;
  color: ThemeColorName;
  link: string | null;
}

/** 段落。bullet が true なら箇条書きの項目にする。 */
export interface Paragraph {
  runs: TextRun[];
  bullet: boolean;
}

