python3 - <<'EOF'
p='slide-deck/src/data/parts.ts'
s=open(p).read()
old=s[s.index('/**\n * 文字の入力を段落に分ける。'):s.index('/** 資料ごとのスクリプトが、キーごとの空の図を作る。')]
new='''/**
 * 文字の入力を段落に分ける。
 * 部分の breakLine と文字の中の改行で段落を分け、部分の bullet はその部分を含む段落に付ける。
 * 空行の段落にも、文字が空の部分を 1 つ置く。段落の文字の大きさ・太字・色を、空行でも書き出しの処理に渡すため。
 * 最後の段落が空なら (最後の部分の breakLine や、末尾の改行で作られたもの) 除く。
 */
function toParagraphs(t: TextInput, d: RunDefaults): Paragraph[] {
  const inputs: RunInput[] = typeof t === "string" ? [{ text: t }] : t;
  let current: Paragraph = { runs: [], bullet: false };
  const paragraphs: Paragraph[] = [current];
  const breakParagraph = (): void => {
    current = { runs: [], bullet: false };
    paragraphs.push(current);
  };
  for (const input of inputs) {
    const lines = input.text.split("\\n");
    lines.forEach((line, i) => {
      if (i > 0) breakParagraph();
      if (input.bullet === true) current.bullet = true;
      const run = {
        text: line,
        fontSize: input.fontSize ?? d.fontSize,
        bold: input.bold ?? d.bold,
        color: input.color ?? d.color,
        link: input.link ?? null,
      };
      if (line === "") {
        // 書式を運ぶための空の部分は、段落に部分がまだ無いときだけ置く
        if (current.runs.length === 0) current.runs.push(run);
        return;
      }
      // 空でない部分が来たら、書式を運ぶために置いた空の部分は要らない
      current.runs = current.runs.filter((r) => r.text !== "");
      current.runs.push(run);
    });
    if (input.breakLine === true) breakParagraph();
  }
  const last = paragraphs[paragraphs.length - 1];
  if (paragraphs.length > 1 && last !== undefined && isBlank(last)) paragraphs.pop();
  return paragraphs;
}

/** 段落に、空でない文字の部分が無いか。 */
function isBlank(p: Paragraph): boolean {
  return p.runs.every((r) => r.text === "");
}

function hasText(paragraphs: Paragraph[]): boolean {
  return paragraphs.some((p) => !isBlank(p));
}

'''
s=s.replace(old,new)
open(p,'w').write(s)
p='slide-deck/src/data/types.ts'
s=open(p).read()
old='/** 段落。bullet が true なら箇条書きの項目にする。 */'
assert old in s
s=s.replace(old,'/**\n * 段落。bullet が true なら箇条書きの項目にする。\n * 空行の段落も、文字が空の部分を 1 つ持ち、その部分が段落の文字の大きさ・太字・色を表す。\n */')
open(p,'w').write(s)
p='slide-deck/tests/data.test.ts'
s=open(p).read()
old='''  test("一部ずつ書式の違う文字は、'''
add='''  test("空行の段落も、文字が空の部分を 1 つ持ち、文字の大きさ・太字・色を持つ", () => {
    const s = slide("k");
    text(s, "a\\n\\nb", 0, 0, 1, 1, { fontSize: 12, bold: true, color: "dk2" });
    const [e] = s.elements;
    assert.ok(e?.kind === "textBox");
    assert.deepEqual(e.text.paragraphs, [
      { runs: [{ text: "a", fontSize: 12, bold: true, color: "dk2", link: null }], bullet: false },
      { runs: [{ text: "", fontSize: 12, bold: true, color: "dk2", link: null }], bullet: false },
      { runs: [{ text: "b", fontSize: 12, bold: true, color: "dk2", link: null }], bullet: false },
    ]);
  });

  test("書式を運ぶ空の部分は、同じ段落に空でない部分が来たら除く", () => {
    const s = slide("k");
    text(s, [{ text: "a\\n" }, { text: "b", bold: true }, { text: "" }], 0, 0, 1, 1);
    const [e] = s.elements;
    assert.ok(e?.kind === "textBox");
    assert.deepEqual(
      e.text.paragraphs.map((p) => p.runs.map((r) => [r.text, r.bold])),
